INSERT INTO `activities` (`id`, `title_id`, `title_en`, `slug`, `description_id`, `description_en`, `image`, `duration_id`, `duration_en`, `min_pax`, `includes_id`, `includes_en`, `order`, `is_featured`, `created_at`, `updated_at`) VALUES
(1, 'Membajak Sawah Tradisional', 'Traditional Rice Field Plowing', 'membajak-sawah-tradisional', 'Rasakan sensasi menjadi petani tradisional dengan membajak sawah menggunakan kerbau yang jinak dan ramah. Dipandu oleh petani lokal berpengalaman, Anda akan belajar teknik membajak tradisional sambil menikmati pemandangan sawah hijau yang asri.', 'Experience the sensation of being a traditional farmer by plowing rice fields using a tame and friendly buffalo. Guided by experienced local farmers.', 'activities/Cl3BIPPFLJroIAy14VozwjF7MlDI5kqtMZG7Six2.jpg', '1-2 jam', '1-2 hours', '1 orang', 'Pemandu, alat membajak, air mineral', 'Guide, plowing tools, mineral water', 1, 1, '2026-07-09 17:14:41', '2026-07-11 08:29:17'),
(2, 'Menanam Padi', 'Rice Planting', 'menanam-padi', 'Belajar cara menanam padi yang benar dari petani lokal. Mulai dari persiapan lahan, pemilihan bibit, hingga teknik menanam yang baik. Cocok untuk study tour sekolah dan keluarga.', 'Learn how to plant rice properly from local farmers. Starting from land preparation, seed selection, to proper planting techniques.', 'activities/RhNJzErEcNZNWBDZmTGr908yhPZo3FDpwv014fbE.jpg', '1-2 jam', '1-2 hours', '1 orang', 'Pemandu, bibit padi, air mineral', 'Guide, rice seeds, mineral water', 2, 1, '2026-07-09 17:14:42', '2026-07-11 08:29:54'),
(3, 'Belajar Gamelan & Karawitan', 'Learning Gamelan & Karawitan', 'belajar-gamelan-karawitan', 'Mainkan alat musik tradisional Jawa seperti saron, bonang, gong, dan kendang. Dipandu oleh seniman lokal, Anda akan belajar memainkan lagu-lagu tradisional.', 'Play traditional Javanese musical instruments such as saron, bonang, gong, and kendang. Guided by local artists.', 'activities/xD66noKi23ctgXd0FiuZviKRZzElUvFpUmyh8GOZ.jpg', '1-2 jam', '1-2 hours', '2 orang', 'Instrumen gamelan, pemandu seni, sertifikat', 'Gamelan instruments, art guide, certificate', 3, 1, '2026-07-09 17:14:42', '2026-07-11 08:31:47'),
(4, 'Belajar Membatik Tulis', 'Learn Batik Making', 'belajar-membatik-tulis', 'Belajar membatik tulis menggunakan canting langsung dari pengrajin berpengalaman. Hasil karya sendiri bisa dibawa pulang sebagai buah tangan berharga.', 'Learn traditional batik making using canting directly from experienced artisans. Take home your own masterpiece.', 'activities/MNMBAWAjxXojOTr0dOJxOgcKkQOoRpQ3KRCSLVlq.jpg', '2-3 jam', '2-3 hours', '2 orang', 'Kain, canting, malam, pewarna, pemandu', 'Fabric, canting, wax, dye, guide', 4, 1, '2026-07-09 17:14:42', '2026-07-11 08:32:07'),
(5, 'Petik Salak Pondoh', 'Salak Pondoh Harvesting', 'petik-salak-pondoh', 'Petik salak pondoh langsung dari pohon di kebun organik. Ditemani petani lokal, belajar memilih salak yang matang sempurna. Salak Pondoh Gabugan terkenal manis!', 'Pick salak pondoh directly from the tree in organic gardens. Accompanied by local farmers, learn to choose perfectly ripe salak.', 'activities/Pk9ogTXNAVLgaV633uafA44dmHwyWa4BEuPFkPjr.jpg', '1 jam', '1 hour', '1 orang', 'Pemandu kebun, salak untuk dicicipi, tas buah', 'Garden guide, salak tasting, fruit bag', 5, 1, '2026-07-09 17:14:42', '2026-07-11 08:32:57'),
(6, 'River Trekking', 'River Trekking', 'river-trekking', 'Susuri aliran sungai jernih dari mata air Gunung Merapi. Air segar, pemandangan bebatuan vulkanik unik, dan ditemani pemandu lokal yang berpengalaman.', 'Explore the clear river flow from Mount Merapi springs. Fresh water, unique volcanic rock views, and experienced local guides.', 'activities/GhYj6kQXDxJfKNaUXQ8qt6u8EF71BjXnK3YNneTy.jpg', '1-2 jam', '1-2 hours', '2 orang', 'Pemandu trekking, alas kaki khusus', 'Trekking guide, special footwear', 6, 1, '2026-07-09 17:14:42', '2026-07-11 08:32:38'),
(7, 'Kuliner Ndeso', 'Village Cuisine', 'kuliner-ndeso', 'Nikmati masakan tradisional khas pedesaan lereng Merapi. Mulai dari Sayur Lodeh Tewel, Sambal Belut Goreng, Nasi Liwet, hingga Wedang Jahe Merapi.', 'Enjoy traditional village cuisine on the slopes of Merapi. From Sayur Lodeh Tewel to Wedang Jahe Merapi.', 'activities/VqLmtF9NeGZJeJKMJePgi1xdMkOhS5UtI8RUqA53.jpg', '1-2 jam', '1-2 hours', '2 orang', 'Paket menu lengkap, lesehan tradisional', 'Complete menu package, traditional seating', 7, 1, '2026-07-09 17:14:42', '2026-07-11 08:33:09');
