INSERT INTO `testimonials` (`id`, `name`, `content`, `content_id`, `content_en`, `locale`, `avatar`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Rifqi Muhammad', 'Berikut beberapa hal favorit saya tentang Desa Wisata Gabugan:\r\n- Rumah adat jawa asri dan nyaman.\r\n- Staf sangat ramah dan membantu.\r\n- Ada banyak aktivitas yang dapat membuat Anda sibuk, mulai dari hiking dan bersepeda hingga kelas memasak dan pertunjukan tari tradisional.\r\n- Makanannya enak dan segar.\r\n- Harga sangat masuk akal.', 'Berikut beberapa hal favorit saya tentang Desa Wisata Gabugan:\r\n- Rumah adat jawa asri dan nyaman.\r\n- Staf sangat ramah dan membantu.\r\n- Ada banyak aktivitas yang dapat membuat Anda sibuk, mulai dari hiking dan bersepeda hingga kelas memasak dan pertunjukan tari tradisional.\r\n- Makanannya enak dan segar.\r\n- Harga sangat masuk akal.', 'Here are some of my favorite things about Gabugan Tourism Village:\r\n- Beautiful and comfortable traditional Javanese house.\r\n- The staff is very friendly and helpful.\r\n- There are plenty of activities to keep you busy, from hiking and cycling to cooking classes and traditional dance performances.\r\n- The food is delicious and fresh.\r\n- Prices are very reasonable.', 'id', NULL, 1, '2026-07-06 21:39:15', '2026-07-06 21:39:15'),
(2, 'Saktiwi Bw', 'Suasana budaya pedesaan yg kental, udara juga sejuk, warganya ramah.', 'Suasana budaya pedesaan yg kental, udara juga sejuk, warganya ramah.', 'There is a strong rural cultural atmosphere, the air is cool, the people are friendly.', 'id', NULL, 1, '2026-07-06 21:39:47', '2026-07-06 21:39:47'),
(3, 'Nitya Wilujeng', 'Ke sini dalam rangka kunjungan edukatif. Banyak paket wisata edukasi yang ditawarkan. Nyaman, sejuk, dan masyarakatnya ramah.', 'Ke sini dalam rangka kunjungan edukatif. Banyak paket wisata edukasi yang ditawarkan. Nyaman, sejuk, dan masyarakatnya ramah.', 'Came here for an educational visit. Many educational tour packages are offered. Comfortable, cool, and the people are friendly.', 'id', NULL, 1, '2026-07-06 21:40:18', '2026-07-06 21:40:18'),
(4, 'Alika Dinanthi', 'tempat yang sangat berarti dan berkesan. Angkatan sekolah saya melakukan program live-in di sini, dan kami belajar banyak dari kegiatan tersebut, kami mencoba membuat manisan salak dan berdiskusi mendalam tentang komunitas lokal jogja dengan pak Tirto, pengalaman yang benar-benar memperkaya yang akan selalu Anda ingat', 'tempat yang sangat berarti dan berkesan. Angkatan sekolah saya melakukan program live-in di sini, dan kami belajar banyak dari kegiatan tersebut, kami mencoba membuat manisan salak dan berdiskusi mendalam tentang komunitas lokal jogja dengan pak Tirto, pengalaman yang benar-benar memperkaya yang akan selalu Anda ingat', 'a very meaningful and memorable place. My school batch did a live-in program here, and we learned a lot from the activity, we tried making sweet salak and had an in-depth discussion about the local community of Jogja with Mr. Tirto, a truly enriching experience that you will always remember', 'id', NULL, 1, '2026-07-06 21:40:41', '2026-07-06 21:40:41');
INSERT INTO `travel_packages` (`id`, `type`, `type_id`, `type_en`, `slug`, `location`, `location_id`, `location_en`, `price`, `description`, `description_id`, `description_en`, `created_at`, `updated_at`, `is_signature`) VALUES
(5, NULL, '1 Hari 1 Malam', '1 Day 1 Night', 'educational-village-homestay', NULL, 'Live In Edukasi', 'Educational Village Homestay', 250000, NULL, '<h3><strong>Deskripsi</strong></h3><p>Temukan pesona otentik Desa Wisata Gabugan melalui pengalaman desa yang mendalam. Peserta akan berinteraksi dengan warga sekitar, mendalami tradisi pedesaan, serta menikmati kegiatan edukasi yang memadukan budaya, pertanian, warisan kuliner, dan alam. Program ini ideal untuk tamasya sekolah, universitas, lembaga pemerintah, perusahaan, dan kelompok masyarakat.</p><h3><strong>Mengapa Memilih Paket Ini?</strong></h3><p>· &nbsp; &nbsp; &nbsp; Interaksi autentik dengan keluarga setempat</p><p>· &nbsp; &nbsp; &nbsp; Kegiatan edukasi langsung</p><p>· &nbsp; &nbsp; &nbsp; Rencana perjalanan fleksibel untuk grup</p><p>· &nbsp; &nbsp; &nbsp; Fasilitator lokal yang berpengalaman</p><p>· &nbsp; &nbsp; &nbsp; Cocok untuk semua kelompok umur</p><h3><strong>Fasilitas</strong></h3><p>· &nbsp; &nbsp; &nbsp; 3 kali makan</p><p>· &nbsp; &nbsp; &nbsp; 1 camilan</p><p>· &nbsp; &nbsp; &nbsp; Homestay dengan Keluarga Lokal</p><p>· &nbsp; &nbsp; &nbsp; Pilih 5 Aktivitas Pendidikan Apa Saja</p><p>· &nbsp; &nbsp; &nbsp; Dukungan Audio Dasar</p><p>· &nbsp; &nbsp; &nbsp; Panduan Aktivitas Profesional</p><p>· &nbsp; &nbsp; &nbsp; Bantuan Bus Kru Gratis</p><p>· &nbsp; &nbsp; &nbsp; Area Parkir Gratis</p><h3><strong>Opsi Aktivitas</strong></h3><p>· &nbsp; &nbsp; &nbsp; Pengalaman Pertanian</p><p>· &nbsp; &nbsp; &nbsp; Perkebunan Salak</p><p>· &nbsp; &nbsp; &nbsp; Workshop Kuliner Tradisional</p><p>· &nbsp; &nbsp; &nbsp; Workshop Membatik</p><p>· &nbsp; &nbsp; &nbsp; Peternakan Burung Puyuh</p><p>· &nbsp; &nbsp; &nbsp; Musik Tradisional Jawa (Gamelan)</p><p>· &nbsp; &nbsp; &nbsp; Perikanan Air Tawar</p><p>· &nbsp; &nbsp; &nbsp; Pembuatan Cinderamata</p><p>· &nbsp; &nbsp; &nbsp; Penjelajahan Sungai &amp; Eksplorasi Desa</p><h3><strong>Hiburan Opsional</strong></h3><p>Sempurnakan kunjungan Anda dengan hiburan tambahan dan layanan pendukung acara.</p><p>· &nbsp; &nbsp; &nbsp; 🎭 Pertunjukan Budaya Tradisional — Rp 1.500.000</p><p>· &nbsp; &nbsp; &nbsp; 🎤 Live Music / Organ Tunggal — Rp 1.500.000</p><p>· &nbsp; &nbsp; &nbsp; 🔊 Sound System Besar — Rp 700.000</p><h3><strong>Catatan</strong></h3><p>• Harga didasarkan pada minimal 100 peserta.<br>• Setiap kelompok dapat memilih hingga lima kegiatan pendidikan.<br>• Kegiatan bergantung pada cuaca dan kondisi musiman.<br>• Rencana perjalanan dapat disesuaikan dengan kebutuhan grup Anda.</p>', '<h3><strong>Overview</strong></h3><p>Discover the authentic charm of Desa Wisata Gabugan through an immersive village experience. Participants will interact with local residents, explore rural traditions, and enjoy educational activities that combine culture, agriculture, culinary heritage, and nature. The program is ideal for school excursions, universities, government institutions, companies, and community groups.</p><h3><strong>Why Choose This Package?</strong></h3><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Authentic interaction with local families</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on educational activities</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Flexible itinerary for groups</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Experienced local facilitators</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Suitable for all age groups</p><h3><strong>Facilities</strong></h3><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 3 Meals</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 1 Snack</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Homestay with Local Families</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Choose Any 5 Educational Activities</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Basic Audio Support</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Professional Activity Guide</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Free Crew Bus Assistance</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Free Parking Area</p><h3><strong>Activity Options</strong></h3><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Agriculture Experience</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Salak Plantation</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Traditional Culinary Workshop</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Batik Workshop</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Quail Farming</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Traditional Javanese Music (Gamelan)</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Freshwater Fishery</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Souvenir Making</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; River Trekking &amp; Village Exploration</p><h3><strong>Optional Entertainment</strong></h3><p>Enhance your visit with additional entertainment and event support services.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 🎭 Traditional Cultural Performance — IDR 1,500,000</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 🎤 Live Music / Organ Tunggal — IDR 1,500,000</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 🔊 Large Sound System — IDR 700,000</p><h3><strong>Notes</strong></h3><p>• Prices are based on a minimum of 100 participants.<br>• Each group may choose up to five educational activities.<br>• Activities are subject to weather and seasonal conditions.<br>• The itinerary can be customized according to your group\'s needs.</p>', '2026-07-08 16:21:28', '2026-07-11 20:30:28', 0),
(8, NULL, '1 Hari 1 Malam', '1 Day 1 Night', 'harmony-village-homestay', NULL, 'Live In Harmoni Desa', 'Harmony Village Homestay', 215000, NULL, '<h3><strong>Deskripsi</strong></h3><p>Temukan pesona otentik Desa Wisata Gabugan melalui pengalaman desa yang mendalam. Peserta akan berinteraksi dengan penduduk setempat, menjelajahi tradisi pedesaan, dan menikmati kegiatan edukatif yang menggabungkan budaya, pertanian, warisan kuliner, dan alam. Program ini ideal untuk kunjungan sekolah, universitas, lembaga pemerintah, perusahaan, dan kelompok masyarakat.</p><h3><strong>Mengapa Memilih Paket Ini?</strong></h3><p>• Interaksi otentik dengan keluarga lokal</p><p>• Aktivitas pendidikan langsung</p><p>• Jadwal fleksibel untuk kelompok</p><p>• Fasilitator lokal berpengalaman</p><p>• Cocok untuk semua kelompok usia</p><h3><strong>Fasilitas</strong></h3><p>• 2 Kali Makan</p><p>• Menginap di rumah penduduk lokal</p><p>• Pilih 5 Aktivitas Pendidikan</p><p>• Dukungan Audio Dasar</p><p>• Pemandu Aktivitas Profesional</p><p>• Bus Antar-Jemput Gratis Bantuan</p><p>• Area Parkir Gratis</p><h3><strong>Pilihan Aktivitas</strong></h3><p>• Pengalaman Pertanian</p><p>• Perkebunan Salak</p><p>• Lokakarya Kuliner Tradisional</p><p>• Lokakarya Batik</p><p>• Peternakan Burung Puyuh</p><p>• Musik Jawa Tradisional (Gamelan)</p><p>• Perikanan Air Tawar</p><p>• Pembuatan Suvenir</p><p>• Trekking Sungai &amp; Eksplorasi Desa</p><h3><strong>Hiburan Opsional</strong></h3><p>Tingkatkan kunjungan Anda dengan hiburan tambahan dan layanan pendukung acara.</p><p>• 🎭 Pertunjukan Budaya Tradisional — Rp 1.500.000</p><p>• 🎤 Musik Live / Organ Tunggal — Rp 1.500.000</p><p>• 🔊 Sistem Suara Besar — ​​Rp 700.000</p><h3><strong>Catatan</strong></h3><p>• Harga berdasarkan minimal 100 peserta.</p><p>• Setiap kelompok dapat memilih hingga lima kegiatan edukatif.</p><p>• Kegiatan bergantung pada kondisi cuaca dan musim.</p><p>• Jadwal dapat disesuaikan sesuai kebutuhan kelompok Anda.</p>', '<h3><strong>Overview</stro